<?php
require_once 'config.php';
require_login();
$message='';
$categories=[];$r=$conn->query("SELECT id,name FROM categories ORDER BY name");while($r&&$row=$r->fetch_assoc())$categories[]=$row;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$categoryId=(int)($_POST['category_id']??0);$stock=max(0,(int)($_POST['stock']??20));$amazon=trim($_POST['amazon_url']??'');$tab=$_POST['tab_name']??'recent';
 if($name===''||$price<=0||$categoryId<=0||!in_array($tab,['trending','recent'],true))$message='Please fill all fields correctly.';
 elseif($amazon!==''&&!filter_var($amazon,FILTER_VALIDATE_URL))$message='Enter a valid product URL.';
 elseif(!isset($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK)$message='Please select an image.';
 else{$allowed=['jpg','jpeg','png','webp'];$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))$message='Only JPG, JPEG, PNG and WEBP images are allowed.';elseif($_FILES['image']['size']>5*1024*1024)$message='Image must be smaller than 5 MB.';else{$new=uniqid('product_',true).'.'.$ext;$dest=__DIR__.'/uploads/'.$new;if(!is_dir(__DIR__.'/uploads'))mkdir(__DIR__.'/uploads',0755,true);if(move_uploaded_file($_FILES['image']['tmp_name'],$dest)){$path='uploads/'.$new;$stmt=$conn->prepare("INSERT INTO products(category_id,name,description,price,image,amazon_url,stock,tab_name) VALUES(?,?,?,?,?,?,?,?)");$stmt->bind_param('issdssis',$categoryId,$name,$description,$price,$path,$amazon,$stock,$tab);if($stmt->execute())$message='Product uploaded successfully.';else{$message='Database error while saving product.';@unlink($dest);}}else$message='Could not upload image.';}}}
$products=[];$r=$conn->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC");while($r&&$row=$r->fetch_assoc())$products[]=$row;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Style Hub Admin</title><link rel="stylesheet" href="style.css"></head><body><header><a class="logo" href="home.php">Style Hub Admin</a><div class="header-right"><a class="auth-btn" href="home.php">Home</a><a class="auth-btn" href="logout.php">Logout</a></div></header><main class="admin-container"><h1>Add Product</h1><p class="admin-note">Manage the enhanced product catalogue. Existing login/registration remains unchanged.</p><?php if($message):?><div class="admin-message"><?=htmlspecialchars($message)?></div><?php endif;?><form class="upload-form" method="post" enctype="multipart/form-data"><label>Product Name</label><input name="name" required><label>Description</label><textarea name="description" rows="4"></textarea><label>Price (₹)</label><input type="number" step="0.01" name="price" required><label>Category</label><select name="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><label>Stock</label><input type="number" name="stock" value="20" min="0" required><label>Product Image</label><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp" required><label>Product URL (optional)</label><input type="url" name="amazon_url" placeholder="https://www.amazon.in/..."><label>Display Tab</label><select name="tab_name"><option value="trending">Trending</option><option value="recent">Recent</option></select><button class="primary-btn" type="submit">Upload Product</button></form><h2 class="admin-list-title">Products</h2><div class="admin-table-wrapper"><table class="admin-table"><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th>Tab</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><img src="<?=htmlspecialchars($p['image'])?>" width="70" height="70" class="table-img"></td><td><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['category'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><?=htmlspecialchars(ucfirst($p['tab_name']))?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
